<?php

namespace App\Http\Controllers\Api\V1;

use App\Models\{Supplier, SupplierDocument, SupplierDocumentRequirement, SupplierDocumentReview, SupplierOnboardingApplication, ApprovalRequest};
use App\Services\{ApprovalService, AuditLogger, AuthorizationService, ProcurementNumberService};
use App\Support\TenantContext;
use Illuminate\Http\{JsonResponse, Request};
use Illuminate\Support\Facades\{DB, Storage};
use Illuminate\Validation\ValidationException;

final class SupplierOnboardingController
{
    private function tenant(): string { return (string) app(TenantContext::class)->id(); }
    private function allow(Request $r, string $permission = 'procurement.manage', ?string $companyId = null): void { abort_unless($r->user() && app(AuthorizationService::class)->allows($r->user(), $this->tenant(), $permission, $companyId), 403); }
    private function appAccess(Request $r, SupplierOnboardingApplication $app): void { abort_unless($app->tenant_id === $this->tenant(), 404); $this->allow($r, 'procurement.manage', $app->company_id); }

    public function summary(Request $r): JsonResponse { $this->allow($r, 'procurement.manage', $r->string('company_id')->toString() ?: null); $q = SupplierOnboardingApplication::where('tenant_id', $this->tenant())->when($r->filled('company_id'), fn ($x) => $x->where('company_id', $r->string('company_id'))); return response()->json(['data' => ['total' => (clone $q)->count(), 'pending_review' => (clone $q)->whereIn('status', ['submitted','under_review','pending_approval'])->count(), 'needs_changes' => (clone $q)->where('status','changes_requested')->count(), 'approved' => (clone $q)->where('approval_status','approved')->count(), 'rejected' => (clone $q)->where('approval_status','rejected')->count(), 'expiring_documents' => SupplierDocument::where('tenant_id',$this->tenant())->whereNotNull('expiry_date')->whereBetween('expiry_date',[now()->toDateString(),now()->addDays(30)->toDateString()])->count()]]); }

    public function index(Request $r): JsonResponse { $this->allow($r, 'procurement.manage', $r->string('company_id')->toString() ?: null); $q = SupplierOnboardingApplication::where('tenant_id',$this->tenant())->with(['supplier','company','documents'])->when($r->filled('company_id'),fn($x)=>$x->where('company_id',$r->string('company_id')))->when($r->filled('status'),fn($x)=>$x->where('status',$r->string('status')))->when($r->filled('search'),function($x)use($r){$s=$r->string('search');$x->where(fn($y)=>$y->where('number','ilike',"%{$s}%")->orWhereHas('supplier',fn($z)=>$z->where('name','ilike',"%{$s}%")->orWhere('code','ilike',"%{$s}%")));})->when($r->filled('date_from'),fn($x)=>$x->whereDate('created_at','>=',$r->date('date_from')))->when($r->filled('date_to'),fn($x)=>$x->whereDate('created_at','<=',$r->date('date_to')))->latest(); return response()->json(['data'=>$q->paginate(min(max($r->integer('per_page',25),10),100)),'summary'=>$this->summary($r)->getData(true)['data']]); }
    public function supplierApplications(Request $r, Supplier $supplier): JsonResponse { abort_unless($supplier->tenant_id===$this->tenant(),404); $this->allow($r,'procurement.manage',$supplier->company_id); return response()->json(['data'=>SupplierOnboardingApplication::where('tenant_id',$this->tenant())->where('supplier_id',$supplier->id)->with(['documents','approvalRequest.actions'])->latest('version')->paginate(25)]); }

    public function store(Request $r, Supplier $supplier, ProcurementNumberService $numbers, AuditLogger $audit): JsonResponse { abort_unless($supplier->tenant_id === $this->tenant(),404); $d=$r->validate(['company_id'=>'required|uuid','application_type'=>'required|in:new_supplier_onboarding,supplier_information_update,supplier_reverification','notes'=>'nullable|string|max:5000']); $this->allow($r,'procurement.manage',$d['company_id']); abort_unless($supplier->company_id===null||$supplier->company_id===$d['company_id'],422,'Supplier is not available to this company.'); $app=DB::transaction(fn()=>SupplierOnboardingApplication::create(['tenant_id'=>$this->tenant(),'company_id'=>$d['company_id'],'supplier_id'=>$supplier->id,'number'=>$numbers->makeFor('SRA',$this->tenant(),$d['company_id']),'application_type'=>$d['application_type'],'notes'=>$d['notes']??null,'submitted_by'=>$r->user()->id,'snapshot'=>$supplier->only(['name','trading_name','supplier_type','business_registration_number','tax_identifier','email','phone','address'])])); $audit->record($r,'supplier.onboarding.created',$this->tenant(),$app,['company_id'=>$app->company_id]); return response()->json(['data'=>$app->load('supplier')],201); }
    public function show(Request $r, SupplierOnboardingApplication $application): JsonResponse { $this->appAccess($r,$application); return response()->json(['data'=>$application->load(['supplier','company','documents.requirement','documents.reviews.reviewer','approvalRequest.definition','approvalRequest.actions.approver'])]); }
    public function update(Request $r, SupplierOnboardingApplication $application, AuditLogger $audit): JsonResponse { $this->appAccess($r,$application); abort_unless(in_array($application->status,['draft','changes_requested'],true),422,'Only draft applications can be edited.'); $d=$r->validate(['notes'=>'nullable|string|max:5000','assigned_reviewer_id'=>'nullable|uuid']); $application->update($d); $audit->record($r,'supplier.onboarding.updated',$this->tenant(),$application); return response()->json(['data'=>$application->fresh()]); }
    public function submit(Request $r, SupplierOnboardingApplication $application, ApprovalService $approvals, AuditLogger $audit): JsonResponse { $this->appAccess($r,$application); abort_unless(in_array($application->status,['draft','changes_requested'],true),422,'Application cannot be submitted in its current state.'); $required=$this->requiredDocuments($application); foreach($required as $req){$ok=$application->documents()->where('requirement_id',$req->id)->where('status','verified')->where(fn($q)=>$q->whereNull('expiry_date')->orWhere('expiry_date','>=',now()->toDateString()))->exists(); if(!$ok)throw ValidationException::withMessages(['documents'=>["Required document missing or unverified: {$req->name}"]]);} $approval=$approvals->create(['tenant_id'=>$this->tenant(),'scenario'=>'supplier_onboarding','requester_id'=>$r->user()->id,'company_id'=>$application->company_id,'document_type'=>SupplierOnboardingApplication::class,'document_id'=>$application->id,'amount'=>'0','currency_code'=>null]); $application->update(['status'=>'pending_approval','approval_status'=>'pending','approval_request_id'=>$approval->id,'submitted_by'=>$r->user()->id,'submitted_at'=>now(),'change_request_reason'=>null]); $audit->record($r,'supplier.onboarding.submitted',$this->tenant(),$application); return response()->json(['data'=>$application->fresh('approvalRequest')]); }
    public function requestChanges(Request $r, SupplierOnboardingApplication $application, AuditLogger $audit): JsonResponse { $this->appAccess($r,$application); $d=$r->validate(['reason'=>'required|string|min:2|max:4000']); $application->update(['status'=>'changes_requested','approval_status'=>'revision_required','change_request_reason'=>$d['reason'],'reviewed_at'=>now()]); $audit->record($r,'supplier.onboarding.changes_requested',$this->tenant(),$application,['reason'=>$d['reason']]); return response()->json(['data'=>$application->fresh()]); }
    public function resubmit(Request $r, SupplierOnboardingApplication $application, ApprovalService $approvals, AuditLogger $audit): JsonResponse { $this->appAccess($r,$application); abort_unless($application->status==='changes_requested',422,'Application is not awaiting resubmission.'); $application->increment('version'); return $this->submit($r,$application->fresh(),$approvals,$audit); }
    public function decide(Request $r, SupplierOnboardingApplication $application, ApprovalService $approvals, AuditLogger $audit, string $decision): JsonResponse { $this->appAccess($r,$application); abort_unless($application->approval_request_id,409,'No approval request exists.'); $d=$r->validate(['remarks'=>['required','string','min:2','max:4000']]); $result=$approvals->decide(ApprovalRequest::whereKey($application->approval_request_id)->firstOrFail(),$r->user(),$decision,$d['remarks']); $application->update(['status'=>$result->state==='approved'?'approved':($result->state==='rejected'?'rejected':'pending_approval'),'approval_status'=>$result->state,'reviewed_at'=>$result->state==='approved'||$result->state==='rejected'?now():null]); $audit->record($r,'supplier.onboarding.'.$decision,$this->tenant(),$application,['remarks'=>$d['remarks']]); return response()->json(['data'=>$application->fresh(['approvalRequest.actions'])]); }
    public function approve(Request $r, SupplierOnboardingApplication $application, ApprovalService $approvals, AuditLogger $audit): JsonResponse { return $this->decide($r,$application,$approvals,$audit,'approved'); }
    public function reject(Request $r, SupplierOnboardingApplication $application, ApprovalService $approvals, AuditLogger $audit): JsonResponse { return $this->decide($r,$application,$approvals,$audit,'rejected'); }
    public function requirements(Request $r): JsonResponse { $this->allow($r,'procurement.manage',$r->string('company_id')->toString() ?: null); $q=SupplierDocumentRequirement::where('tenant_id',$this->tenant())->where('is_active',true)->when($r->filled('company_id'),fn($x)=>$x->where(fn($y)=>$y->whereNull('company_id')->orWhere('company_id',$r->string('company_id')))); return response()->json(['data'=>$q->orderBy('name')->get()]); }
    public function saveRequirement(Request $r, AuditLogger $audit): JsonResponse { $d=$r->validate(['company_id'=>'nullable|uuid','name'=>'required|string|max:200','supplier_type'=>'nullable|string|max:50','country'=>'nullable|string|max:100','is_required'=>'boolean','requires_expiry_date'=>'boolean','requires_manual_verification'=>'boolean','max_file_size_kb'=>'integer|min:1|max:102400','allowed_mime_types'=>'nullable|array','is_active'=>'boolean']); $this->allow($r,'organization.manage',$d['company_id']??null); $m=SupplierDocumentRequirement::create(['tenant_id'=>$this->tenant(),...$d]); $audit->record($r,'supplier.document_requirement.created',$this->tenant(),$m); return response()->json(['data'=>$m],201); }
    public function documents(Request $r, Supplier $supplier): JsonResponse { abort_unless($supplier->tenant_id===$this->tenant(),404); $this->allow($r,'procurement.manage',$supplier->company_id); return response()->json(['data'=>$supplier->documents()->with(['requirement','reviews.reviewer'])->latest()->paginate(25)]); }
    public function upload(Request $r, Supplier $supplier, AuditLogger $audit): JsonResponse { abort_unless($supplier->tenant_id===$this->tenant(),404); $d=$r->validate(['company_id'=>'required|uuid','application_id'=>'nullable|uuid','requirement_id'=>'nullable|uuid','document_type'=>'required|string|max:120','file'=>'required|file|max:102400|mimes:pdf,jpg,jpeg,png,webp','issue_date'=>'nullable|date','expiry_date'=>'nullable|date|after_or_equal:issue_date']); $this->allow($r,'procurement.manage',$d['company_id']); abort_unless($supplier->company_id===null||$supplier->company_id===$d['company_id'],422,'Supplier is not available to this company.'); $file=$r->file('file'); $requirement=$d['requirement_id']?SupplierDocumentRequirement::where('tenant_id',$this->tenant())->whereKey($d['requirement_id'])->where(fn($q)=>$q->whereNull('company_id')->orWhere('company_id',$d['company_id']))->firstOrFail():null; if($requirement&&$file->getSize()>($requirement->max_file_size_kb*1024))throw ValidationException::withMessages(['file'=>['The file exceeds the configured requirement size limit.']]); if($requirement&&$requirement->allowed_mime_types&&!in_array($file->getMimeType(),$requirement->allowed_mime_types,true))throw ValidationException::withMessages(['file'=>['The file type is not allowed by the configured requirement.']]); if($requirement&&$requirement->requires_expiry_date&&!$d['expiry_date'])throw ValidationException::withMessages(['expiry_date'=>['An expiry date is required for this document type.']]); if(!empty($d['application_id']))abort_unless(SupplierOnboardingApplication::where('tenant_id',$this->tenant())->whereKey($d['application_id'])->where('supplier_id',$supplier->id)->where('company_id',$d['company_id'])->exists(),404); $path=$file->store('supplier-documents/'.$this->tenant().'/'.$supplier->id,'local'); $version=(int)$supplier->documents()->where('company_id',$d['company_id'])->where('document_type',$d['document_type'])->max('version')+1; $doc=SupplierDocument::create(['tenant_id'=>$this->tenant(),'company_id'=>$d['company_id'],'supplier_id'=>$supplier->id,'application_id'=>$d['application_id']??null,'requirement_id'=>$d['requirement_id']??null,'uploaded_by'=>$r->user()->id,'document_type'=>$d['document_type'],'original_filename'=>basename($file->getClientOriginalName()),'storage_path'=>$path,'mime_type'=>$file->getMimeType(),'file_size'=>$file->getSize(),'version'=>$version,'status'=>'submitted','issue_date'=>$d['issue_date']??null,'expiry_date'=>$d['expiry_date']??null]); $audit->record($r,'supplier.document.uploaded',$this->tenant(),$doc,['supplier_id'=>$supplier->id,'version'=>$version]); return response()->json(['data'=>$doc],201); }
    public function download(Request $r, SupplierDocument $document) { abort_unless($document->tenant_id===$this->tenant(),404); $this->allow($r,'procurement.manage',$document->company_id); abort_unless(Storage::disk('local')->exists($document->storage_path),404); return Storage::disk('local')->download($document->storage_path,$document->original_filename,['Content-Type'=>$document->mime_type]); }
    public function review(Request $r, SupplierDocument $document, AuditLogger $audit, string $decision): JsonResponse { abort_unless($document->tenant_id===$this->tenant(),404); $this->allow($r,'procurement.manage',$document->company_id); $d=$r->validate(['notes'=>[$decision==='rejected'?'required':'nullable','string','max:4000']]); abort_unless(in_array($decision,['verified','rejected','under_review'],true),422); DB::transaction(function()use($document,$r,$d,$decision){$document->update(['status'=>$decision,'verified_by'=>$decision==='verified'?$r->user()->id:null,'verified_at'=>$decision==='verified'?now():null,'review_notes'=>$d['notes']??null]); SupplierDocumentReview::create(['tenant_id'=>$this->tenant(),'supplier_document_id'=>$document->id,'reviewer_id'=>$r->user()->id,'decision'=>$decision,'notes'=>$d['notes']??null,'reviewed_at'=>now()]);}); $audit->record($r,'supplier.document.'.$decision,$this->tenant(),$document); return response()->json(['data'=>$document->fresh('reviews')]); }
    public function eligibility(Request $r, Supplier $supplier): JsonResponse { abort_unless($supplier->tenant_id===$this->tenant(),404); $companyId=$r->string('company_id')->toString()?:$supplier->company_id; $this->allow($r,'procurement.manage',$companyId); $app=SupplierOnboardingApplication::where('tenant_id',$this->tenant())->where('supplier_id',$supplier->id)->where('company_id',$companyId)->latest('version')->first(); $missing=$app?$this->requirementsFor($app)->filter(fn($req)=>!$supplier->documents()->where('requirement_id',$req->id)->where('status','verified')->where(fn($q)=>$q->whereNull('expiry_date')->orWhere('expiry_date','>=',now()->toDateString()))->exists())->pluck('name')->values()->all():[]; $eligible=$supplier->status==='active'&&$app?->approval_status==='approved'&&!$missing; return response()->json(['data'=>['eligible'=>$eligible,'reasons'=>$eligible?[]:array_values(array_filter([$supplier->status!=='active'?'Supplier is not active.':null,!$app?'No approved onboarding application.':null,$missing? 'Missing or unverified documents: '.implode(', ',$missing):null])),'application'=>$app]]); }
    private function requiredDocuments(SupplierOnboardingApplication $app) { return $this->requirementsFor($app); }
    private function requirementsFor(SupplierOnboardingApplication $app) { return SupplierDocumentRequirement::where('tenant_id',$this->tenant())->where('is_active',true)->where('is_required',true)->where(fn($q)=>$q->whereNull('company_id')->orWhere('company_id',$app->company_id))->where(fn($q)=>$q->whereNull('supplier_type')->orWhere('supplier_type',$app->supplier->supplier_type))->get(); }
}
